document.addEventListener("click",async(event)=>{const button=event.target.closest("[data-share-copy]");if(!button)return;const status=button.closest(".share-actions").querySelector(".share-copy-status");const url=document.querySelector('link[rel="canonical"]')?.href||location.href;try{await navigator.clipboard.writeText(url);status.textContent="URLをコピーしました。";}catch{const input=document.createElement("textarea");input.value=url;input.style.position="fixed";input.style.opacity="0";document.body.append(input);input.select();const copied=document.execCommand("copy");input.remove();status.textContent=copied?"URLをコピーしました。":`コピーできませんでした。URL:${url}`;}});
